package com.jobpilot.job;import com.jobpilot.config.CurrentUserService;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.springframework.http.HttpStatus.NOT_FOUND;
@Service public class JobService{private final JobOfferRepository repo;private final CurrentUserService current;public JobService(JobOfferRepository r,CurrentUserService c){repo=r;current=c;}public List<JobDtos.JobView>list(){return repo.findByUserIdOrderByCreatedAtDesc(current.get().getId()).stream().map(JobDtos::view).toList();}public JobDtos.JobView create(JobDtos.CreateJob d){var j=new JobOffer();j.setUser(current.get());j.setTitle(d.title());j.setCompany(d.company());j.setLocation(d.location());j.setRemote(d.remote());j.setSalaryMin(d.salaryMin());j.setSalaryMax(d.salaryMax());j.setDescription(d.description());j.setUrl(d.url());return JobDtos.view(repo.save(j));}public JobOffer owned(Long id){return repo.findByIdAndUserId(id,current.get().getId()).orElseThrow(()->new ResponseStatusException(NOT_FOUND,"Job not found"));}public void delete(Long id){repo.delete(owned(id));}}
